package com.bananalab.lite;
import android.content.*;import java.io.*;import java.util.*;import org.json.*;import dalvik.system.DexClassLoader;
/** Complete editable Java copy, compiler-only. It never executes arbitrary workspace classes. */
final class JavaProject{
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-java-project",0);}
 static File api(Context c)throws Exception{String sha=new JSONObject(AppJavaChat.asset(c,"java-tools/android-api-provenance.json",12000)).getString("sha256");if(!sha.matches("[a-f0-9]{64}"))throw new IOException("Identidad de API inválida.");File file=new File(c.getDir("java-project-tools",0),"android-api-"+sha.substring(0,16)+".jar");if(!file.exists())try(InputStream in=c.getAssets().open("java-tools/android-api.jar")){OnDeviceJava.immutable(file,OnDeviceJava.bytes(in,12000000));}java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] bytes=new byte[8192];int count;while((count=in.read(bytes))!=-1)digest.update(bytes,0,count);}StringBuilder actual=new StringBuilder();for(byte value:digest.digest())actual.append(Integer.toHexString((value&255)|256).substring(1));if(!actual.toString().equals(sha))throw new IOException("La API de compilación no coincide con esta versión.");return file;}
 static String fingerprint(Context c)throws Exception{return JavaMethodEditor.hash(AppJavaChat.asset(c,"code-map.json",1500000));}
 static void ensure(Context c)throws Exception{String base=prefs(c).getString("base","");String current=fingerprint(c);if(base.isEmpty()){if(!prefs(c).edit().putString("base",current).putString("working","{}").putString("accepted","{}").commit())throw new IOException("No pude iniciar la copia del proyecto.");}else if(!base.equals(current))throw new IllegalArgumentException("La app cambió de versión. Usá actualiza base proyecto java para conservar tus ediciones sobre las fuentes nuevas y volver a compilarlas.");}
 static JSONObject working(Context c)throws Exception{ensure(c);return new JSONObject(prefs(c).getString("working","{}"));}
 static Map<String,String> files(Context c,JSONObject overrides)throws Exception{JSONArray index=new JSONObject(AppJavaChat.asset(c,"code-map.json",1500000)).getJSONArray("files");Map<String,String> files=new TreeMap<>();for(int i=0;i<index.length();i++){String name=index.getJSONObject(i).getString("name");JavaSourceEdit.filename(name);files.put(name,AppJavaChat.asset(c,"app-source/"+name,250000));}Iterator<String> names=overrides.keys();while(names.hasNext()){String name=names.next();JavaSourceEdit.filename(name);files.put(name,overrides.getString(name));}return files;}
 static String source(Context c,String name)throws Exception{JavaSourceEdit.filename(name);String text=files(c,working(c)).get(name);if(text==null)throw new IllegalArgumentException("El archivo no está en la copia Java.");return text;}
 static synchronized void stageBatch(Context c,Map<String,String> files)throws Exception{ensure(c);JSONObject next=working(c);for(Map.Entry<String,String> e:files.entrySet()){JavaSourceEdit.filename(e.getKey());String content=e.getValue();if(content.length()>150000||!content.contains("package com.bananalab.lite;"))throw new IOException("Fuente fuera del alcance.");next.put(e.getKey(),content);}if(next.toString().length()>1000000)throw new IOException("El lote supera1MB.");if(!prefs(c).edit().putString("working",next.toString()).putInt("revision",prefs(c).getInt("revision",0)+1).remove("compiledHash").commit())throw new IOException("No pude guardar el lote.");}
 static synchronized void stage(Context c,String name,String content)throws Exception{ensure(c);JavaSourceEdit.filename(name);if(content.length()>150000||!content.contains("package com.bananalab.lite;"))throw new IllegalArgumentException("Archivo demasiado largo o fuera del paquete com.bananalab.lite.");JSONObject changes=working(c);changes.put(name,content);if(changes.toString().length()>1000000)throw new IllegalArgumentException("Los cambios del proyecto superan1MB.");if(!prefs(c).edit().putString("working",changes.toString()).putInt("revision",prefs(c).getInt("revision",0)+1).remove("compiledHash").commit())throw new IOException("No pude guardar el archivo de trabajo.");}
 static synchronized String compile(Context c)throws Exception{return compile(c,working(c),true);}
 static synchronized String compile(Context c,JSONObject changes,boolean record)throws Exception{ensure(c);String hash=JavaMethodEditor.hash(changes.toString()+fingerprint(c));int revision=prefs(c).getInt("revision",0);Map<String,String> sources=files(c,changes);File root=new File(c.getDir("java-project",0),"build-"+UUID.randomUUID());File input=new File(root,"src"),output=new File(root,"classes");if(!input.mkdirs()||!output.mkdirs())throw new IOException("No pude crear la construcción de prueba.");List<String> args=new ArrayList<>(Arrays.asList("-1.8","-proc:none","-encoding","UTF-8","-warn:none","-bootclasspath",api(c).getAbsolutePath(),"-d",output.getAbsolutePath()));for(Map.Entry<String,String> e:sources.entrySet()){if(Thread.currentThread().isInterrupted())throw new IOException("Compilación cancelada.");File file=new File(input,e.getKey());try(FileOutputStream out=new FileOutputStream(file)){out.write(e.getValue().getBytes("UTF-8"));}args.add(file.getAbsolutePath());}
  File opt=new File(OnDeviceJava.home(c),"project-opt");opt.mkdirs();ClassLoader loader=new DexClassLoader(OnDeviceJava.tool(c,"compiler.jar").getAbsolutePath(),opt.getAbsolutePath(),null,c.getClassLoader());StringWriter diagnostics=new StringWriter();PrintWriter writer=new PrintWriter(diagnostics);Class<?> type=loader.loadClass("org.eclipse.jdt.internal.compiler.batch.Main");Object compiler=type.getConstructor(PrintWriter.class,PrintWriter.class,boolean.class).newInstance(writer,writer,false);JavaChat.phase("Android: comprobando los "+sources.size()+" archivos Java…");boolean ok=(Boolean)type.getMethod("compile",String[].class).invoke(compiler,new Object[]{args.toArray(new String[0])});writer.flush();String log=diagnostics.toString();String report=(ok?"Compilación completa aprobada":"La copia Java no compila")+" · "+sources.size()+" archivos.\n"+log.substring(0,Math.min(7000,log.length()))+"\nNo ejecuté las clases, no generé un APK ni cambié la app instalada.";if(!record){prefs(c).edit().putString("candidateReport",report).commit();return report;}SharedPreferences.Editor edit=prefs(c).edit().putString("report",report).putString("build",root.getAbsolutePath());if(ok&&revision==prefs(c).getInt("revision",0))edit.putString("compiledHash",hash);else edit.remove("compiledHash");if(!edit.commit())throw new IOException("No pude guardar el resultado de compilación.");return report;}
 static synchronized String accept(Context c)throws Exception{JSONObject work=working(c);String hash=JavaMethodEditor.hash(work.toString()+fingerprint(c));if(!hash.equals(prefs(c).getString("compiledHash","")))throw new IllegalArgumentException("Compilá los cambios actuales antes de guardar una versión.");JSONArray old=new JSONArray(prefs(c).getString("history","[]")),next=new JSONArray();for(int i=Math.max(0,old.length()-3);i<old.length();i++)next.put(old.getJSONObject(i));next.put(new JSONObject(prefs(c).getString("accepted","{}")));if(!prefs(c).edit().putString("history",next.toString()).putString("accepted",work.toString()).commit())throw new IOException("No pude guardar la versión de fuentes.");return "Guardé una versión comprobada. Para incorporarla al núcleo compatible: reconstruye mi apk e instalá Banana.apk.";}
 static synchronized String undo(Context c)throws Exception{ensure(c);JSONArray history=new JSONArray(prefs(c).getString("history","[]"));if(history.length()==0)return "No hay una versión anterior de fuentes.";JSONObject previous=history.getJSONObject(history.length()-1);JSONArray next=new JSONArray();for(int i=0;i<history.length()-1;i++)next.put(history.getJSONObject(i));if(!prefs(c).edit().putString("working",previous.toString()).putString("accepted",previous.toString()).putString("history",next.toString()).putInt("revision",prefs(c).getInt("revision",0)+1).remove("compiledHash").commit())throw new IOException("No pude recuperar las fuentes.");return "Recuperé la versión anterior de la copia Java; la app instalada se conserva.";}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=ChatLanguage.normalize(input);try{
  if(q.equals("especialista java android"))return MobileCore.say(c,"Especialista Java propio · Android\n• prepara proyecto java: copia todos los Java instalados.\n• compila proyecto java: comprueba todos los archivos.\n• entrena especialista java: MLP propio desde cero, sin modelos externos.\n• edita metodo java SceneTiming.java#seconds: return frames(d)+(float)VideoExporter.FPS;\n• propone cambio java SceneTiming.java#seconds: dividir cuadros por cuadros por segundo\n• ver cambios proyecto java / guarda version proyecto java / deshace version proyecto java.\nLas fuentes generales se compilan. Para conectar AnimationProfile, socialReply o celebration: sustituciones java. El modelo sólo propone seis operaciones aritméticas; no es un programador general.","app_ajuste");
  if(q.matches("prepara proyecto java|estado proyecto java")){ensure(c);Map<String,String> files=files(c,working(c));return MobileCore.say(c,"Copia Java · "+files.size()+" archivos · cambios en "+working(c).length()+" archivos · revisión "+prefs(c).getInt("revision",0)+"\nEditable y compilable en Android; las clases compatibles pueden incorporarse al núcleo de Banana.apk.","app_ajuste");}
  if(q.equals("actualiza base proyecto java")){String previous=prefs(c).getString("base","");if(previous.equals(fingerprint(c)))return MobileCore.say(c,"La base Java ya está actualizada.","app_ajuste");JSONObject backup=new JSONObject().put("base",previous).put("working",prefs(c).getString("working","{}")).put("accepted",prefs(c).getString("accepted","{}")).put("history",prefs(c).getString("history","[]"));if(!prefs(c).edit().putString("previousBase",backup.toString()).putString("base",fingerprint(c)).putInt("revision",prefs(c).getInt("revision",0)+1).remove("compiledHash").commit())throw new IOException("No pude actualizar la base.");return MobileCore.say(c,"Actualicé la base conservando tus archivos editados y una copia anterior. Compilá y revisá los métodos antes de activarlos.","app_ajuste");}
  if(q.equals("ver copia java anterior"))return MobileCore.say(c,prefs(c).getString("previousBase","Sin copia anterior."),"app_ajuste");
  if(q.equals("reinicia proyecto java")){if(!prefs(c).edit().clear().commit())throw new IOException("No pude reiniciar la copia.");ensure(c);return MobileCore.say(c,"Reinicié sólo la copia de fuentes. Tus escenas y los módulos activos se conservan.","app_ajuste");}
  if(q.equals("descarta cambios proyecto java")){ensure(c);if(!prefs(c).edit().putString("working",prefs(c).getString("accepted","{}")).putInt("revision",prefs(c).getInt("revision",0)+1).remove("compiledHash").commit())throw new IOException("No pude descartar los cambios.");return MobileCore.say(c,"Volví a la última versión guardada de fuentes.","app_ajuste");}
  if(q.equals("ver cambios proyecto java"))return MobileCore.say(c,working(c).toString(2),"app_ajuste");
  if(q.equals("guarda version proyecto java"))return MobileCore.say(c,accept(c),"app_ajuste");if(q.equals("deshace version proyecto java"))return MobileCore.say(c,undo(c),"app_ajuste");
  if(q.equals("compila proyecto java")||q.equals("entrena especialista java")){JavaChat.owner=Thread.currentThread();try{return MobileCore.say(c,q.startsWith("compila")?compile(c):JavaEditModel.train(c),"app_ajuste");}finally{JavaChat.owner=null;JavaChat.progress="";}}
  if(q.equals("estado especialista java")){JavaEditModel m=JavaEditModel.current(c);return MobileCore.say(c,"MLP propio · 2454 parámetros · seis operaciones\nEntrenamiento "+m.trainCorrect+"/36; validación "+m.testCorrect+"/12; evaluación separada "+m.finalCorrect+"/12.\nEvalúa selección de operador, no programación Java general. La evaluación usa frases distintas, pero las mismas seis tareas aritméticas.","app_ajuste");}
  java.util.regex.Matcher edit=java.util.regex.Pattern.compile("(?is)^(edita metodo java|propone cambio java) ([A-Za-z][A-Za-z0-9_]*\\.java)#([A-Za-z_$][A-Za-z0-9_$]*)\\s*:\\s*(.+)$").matcher(input.trim());if(edit.matches()){String file=edit.group(2),method=edit.group(3),body=edit.group(4);String before=source(c,file),after;if(edit.group(1).equalsIgnoreCase("edita metodo java"))after=JavaSourceEdit.replace(before,method,body);else{JavaEditModel model=JavaEditModel.current(c);float confidence=model.confidence(body);if(confidence<.2f||!JavaEditModel.covered(body))throw new IllegalArgumentException("El especialista no distingue la operación con suficiente margen. Editá manualmente o reformulá.");String operation=JavaEditModel.OPS[model.predict(body)];after=JavaSourceEdit.arithmetic(before,method,operation);prefs(c).edit().putString("proposal","Operación propuesta por el modelo: "+operation+"; margen no calibrado: "+confidence).apply();}stage(c,file,after);int[] old=JavaSourceEdit.method(before,method),next=JavaSourceEdit.method(after,method);return MobileCore.say(c,"Copia de "+file+"#"+method+" editada.\nANTES:\n"+before.substring(old[0],old[1])+"\nDESPUÉS:\n"+after.substring(next[0],next[1])+"\nCompilá el proyecto antes de guardar la versión. La app activa no cambió.","app_ajuste");}
  java.util.regex.Matcher file=java.util.regex.Pattern.compile("(?is)^escribe archivo java ([A-Za-z][A-Za-z0-9_]*\\.java)\\s*:\\s*(.+)$").matcher(input.trim());if(file.matches()){stage(c,file.group(1),file.group(2));return MobileCore.say(c,"Guardé el archivo en la copia de trabajo. Podés editar otros archivos y compilar el conjunto.","app_ajuste");}
 }catch(Exception e){return MobileCore.say(c,"No activé código general: "+AndroidRepair.summary(e),"app_ajuste");}return null;}
}
